    const user = await db.users.findById(userId);
    if (user.credits < 2) {
        alert("Credit khatam ho gaye, laude. Paise daal ya baat band.");
        return;
    }

    // 2. Deduct credits
    await db.users.decrementCredits(userId, 2);

    // 3. Log the message
    await db.message_logs.create({
        user_id: userId,
        message_content: messageText,
        credits_deducted: 2
    });

    // 4. Return AI Response
    return getAIResponse(messageText);
}
